from __future__ import annotations

"""Convert between raw PCM16 audio sizes and milliseconds.

The Realtime API streams 24 kHz, 16-bit, mono PCM audio. That fixes the bytes
per millisecond, which lets the rest of the system reason about audio purely in
integer milliseconds instead of carrying byte blobs around.
"""

SAMPLE_RATE_HZ = 24_000
BITS_PER_SAMPLE = 16
CHANNELS = 1

BYTES_PER_SAMPLE = (BITS_PER_SAMPLE // 8) * CHANNELS
BYTES_PER_MS = SAMPLE_RATE_HZ * BYTES_PER_SAMPLE // 1000  # 48 bytes per ms


def bytes_to_ms(num_bytes: int) -> int:
    """Whole milliseconds represented by ``num_bytes`` of PCM16 audio."""

    if num_bytes < 0:
        raise ValueError("num_bytes must be non-negative")
    return num_bytes // BYTES_PER_MS


def ms_to_bytes(ms: int) -> int:
    if ms < 0:
        raise ValueError("ms must be non-negative")
    return ms * BYTES_PER_MS


def clamp_ms(ms: int, lower: int, upper: int) -> int:
    """Clamp ``ms`` into the inclusive ``[lower, upper]`` range."""

    if upper < lower:
        raise ValueError("upper bound below lower bound")
    return max(lower, min(ms, upper))


class AudioClock:
    """Tracks a running audio position in milliseconds."""

    def __init__(self) -> None:
        self._position_ms = 0

    @property
    def position_ms(self) -> int:
        return self._position_ms

    def advance_bytes(self, num_bytes: int) -> int:
        self._position_ms += bytes_to_ms(num_bytes)
        return self._position_ms

    def advance_ms(self, ms: int) -> int:
        if ms < 0:
            raise ValueError("ms must be non-negative")
        self._position_ms += ms
        return self._position_ms

    def reset(self) -> None:
        self._position_ms = 0

