from __future__ import annotations

"""Client-to-server commands the session sends back during a barge-in.

Two commands matter here:

- ``response.cancel`` stops the model generating more of the current response.
- ``conversation.item.truncate`` rewrites the server-side history so the
  assistant item only contains the audio the user actually heard. Its
  ``audio_end_ms`` is the contract: it must equal what was played, or the model
  keeps believing it said words the user never received.
"""

from dataclasses import dataclass


CANCEL = "response.cancel"
TRUNCATE = "conversation.item.truncate"


@dataclass(frozen=True)
class CancelResponse:
    response_id: str
    type: str = CANCEL

    def to_wire(self) -> dict:
        return {"type": self.type, "response_id": self.response_id}


@dataclass(frozen=True)
class TruncateItem:
    item_id: str
    audio_end_ms: int
    content_index: int = 0
    type: str = TRUNCATE

    def __post_init__(self) -> None:
        if self.audio_end_ms < 0:
            raise ValueError("audio_end_ms must be non-negative")
        if self.content_index < 0:
            raise ValueError("content_index must be non-negative")

    def to_wire(self) -> dict:
        return {
            "type": self.type,
            "item_id": self.item_id,
            "content_index": self.content_index,
            "audio_end_ms": self.audio_end_ms,
        }


def is_cancel(command: object) -> bool:
    return isinstance(command, CancelResponse)


def is_truncate(command: object) -> bool:
    return isinstance(command, TruncateItem)


def commands_to_wire(commands: list[object]) -> list[dict]:
    wire: list[dict] = []
    for command in commands:
        to_wire = getattr(command, "to_wire", None)
        if to_wire is None:
            raise TypeError(f"not a command: {command!r}")
        wire.append(to_wire())
    return wire

