from __future__ import annotations

"""Local playback buffer for assistant audio, per response.

Audio deltas arrive faster than they play, so at any instant the buffer holds
more audio than the speaker has actually emitted. That look-ahead is normal.

A barge-in changes the rules. When the user starts talking over the assistant,
the client flushes whatever it had buffered ahead of the playback cursor (the
user never hears it) and stops. From that point on, any further audio that
belongs to the interrupted response must not reach the speaker — otherwise the
assistant audibly keeps talking after the user cut in.

Each response gets its own segment so interrupting one response never silences
the next one that starts after the user finishes.
"""

from dataclasses import dataclass


@dataclass
class _Segment:
    response_id: str
    buffered_ms: int = 0
    interrupted: bool = False
    cursor_ms: int = 0
    stale_ms: int = 0


class PlaybackBuffer:
    def __init__(self) -> None:
        self._segments: dict[str, _Segment] = {}
        self._order: list[str] = []
        self._dropped_deltas = 0

    def _segment(self, response_id: str) -> _Segment:
        segment = self._segments.get(response_id)
        if segment is None:
            segment = _Segment(response_id=response_id)
            self._segments[response_id] = segment
            self._order.append(response_id)
        return segment

    def accept_audio(self, response_id: str, ms: int) -> bool:
        """Take in one audio delta for a response.

        Returns True if the audio was queued for playback, False if it was
        discarded.
        """

        if ms < 0:
            raise ValueError("ms must be non-negative")
        segment = self._segment(response_id)
        segment.buffered_ms += ms
        return True

    def interrupt(self, response_id: str, cursor_ms: int) -> None:
        """Barge-in: flush look-ahead past what the user actually heard."""

        if cursor_ms < 0:
            raise ValueError("cursor_ms must be non-negative")
        segment = self._segment(response_id)
        segment.interrupted = True
        segment.cursor_ms = cursor_ms
        # Anything buffered beyond the cursor was never heard; drop it.
        if segment.buffered_ms > cursor_ms:
            segment.buffered_ms = cursor_ms

    def heard_ms(self, response_id: str) -> int:
        """Milliseconds the user actually heard for this response."""

        segment = self._segment(response_id)
        if segment.interrupted:
            return segment.cursor_ms
        return segment.buffered_ms

    def stale_ms(self, response_id: str) -> int:
        """Audio that reached the speaker after the barge-in (should be zero)."""

        segment = self._segment(response_id)
        if not segment.interrupted:
            return 0
        return max(0, segment.buffered_ms - segment.cursor_ms)

    def is_interrupted(self, response_id: str) -> bool:
        return self._segment(response_id).interrupted

    def buffered_ms(self, response_id: str) -> int:
        return self._segment(response_id).buffered_ms

    @property
    def dropped_delta_count(self) -> int:
        return self._dropped_deltas

    def total_stale_ms(self) -> int:
        return sum(self.stale_ms(rid) for rid in self._order)

    def total_heard_ms(self) -> int:
        return sum(self.heard_ms(rid) for rid in self._order)

    def response_ids(self) -> list[str]:
        return list(self._order)

    def interrupted_response_ids(self) -> list[str]:
        return [rid for rid in self._order if self._segments[rid].interrupted]

    def cursor_ms(self, response_id: str) -> int:
        """Where the user stopped hearing this response (0 if never interrupted)."""

        return self._segment(response_id).cursor_ms

    def segment_summary(self, response_id: str) -> dict[str, object]:
        segment = self._segment(response_id)
        return {
            "response_id": segment.response_id,
            "buffered_ms": segment.buffered_ms,
            "interrupted": segment.interrupted,
            "cursor_ms": segment.cursor_ms,
            "heard_ms": self.heard_ms(response_id),
            "stale_ms": self.stale_ms(response_id),
        }

    def summary(self) -> list[dict[str, object]]:
        return [self.segment_summary(rid) for rid in self._order]

