from __future__ import annotations

"""Decoded Realtime API server events plus builders used to script sessions.

The session driver consumes an ordered list of these. The shapes that matter:

- ``response.created`` — a new assistant response begins; it owns one output
  ``item`` whose ``item_id`` is what truncation later targets.
- ``response.audio.delta`` — a chunk of synthesized audio for a response. Chunks
  keep arriving slightly after a barge-in until the cancel takes effect.
- ``input_audio_buffer.speech_started`` — server VAD heard the user start
  talking (a barge-in). The client reports how many ms of the current response
  it had actually played out as ``playback_cursor_ms``.
- ``response.audio.done`` / ``response.done`` — the response finished (or was
  cancelled).
"""

import base64
from dataclasses import dataclass

from audio_clock import bytes_to_ms, ms_to_bytes


# Event type tags (as they appear on the wire).
RESPONSE_CREATED = "response.created"
RESPONSE_AUDIO_DELTA = "response.audio.delta"
RESPONSE_AUDIO_DONE = "response.audio.done"
RESPONSE_DONE = "response.done"
SPEECH_STARTED = "input_audio_buffer.speech_started"

# Response lifecycle states.
STATUS_IN_PROGRESS = "in_progress"
STATUS_COMPLETED = "completed"
STATUS_CANCELLED = "cancelled"


@dataclass(frozen=True)
class RealtimeEvent:
    """One decoded server event for a single-response-at-a-time session."""

    type: str
    response_id: str | None = None
    item_id: str | None = None
    audio_bytes: int = 0
    status: str | None = None
    playback_cursor_ms: int = 0

    def __post_init__(self) -> None:
        if not self.type:
            raise ValueError("event type is required")
        if self.audio_bytes < 0:
            raise ValueError("audio_bytes must be non-negative")
        if self.playback_cursor_ms < 0:
            raise ValueError("playback_cursor_ms must be non-negative")

    @property
    def audio_ms(self) -> int:
        return bytes_to_ms(self.audio_bytes)

    def is_audio_delta(self) -> bool:
        return self.type == RESPONSE_AUDIO_DELTA

    def is_barge_in(self) -> bool:
        return self.type == SPEECH_STARTED

    @classmethod
    def from_raw(cls, raw: dict) -> "RealtimeEvent":
        event_type = str(raw.get("type", ""))
        audio_bytes = 0
        delta_b64 = raw.get("delta")
        if delta_b64:
            audio_bytes = len(base64.b64decode(delta_b64))
        elif raw.get("audio_bytes"):
            audio_bytes = int(raw["audio_bytes"])
        return cls(
            type=event_type,
            response_id=raw.get("response_id"),
            item_id=raw.get("item_id"),
            audio_bytes=audio_bytes,
            status=raw.get("status"),
            playback_cursor_ms=int(raw.get("playback_cursor_ms", 0)),
        )


# --- builders (used by the driver's callers and by tests) ---

def response_created(response_id: str, item_id: str) -> RealtimeEvent:
    return RealtimeEvent(type=RESPONSE_CREATED, response_id=response_id, item_id=item_id)


def audio_delta(response_id: str, ms: int) -> RealtimeEvent:
    if ms < 0:
        raise ValueError("ms must be non-negative")
    return RealtimeEvent(
        type=RESPONSE_AUDIO_DELTA,
        response_id=response_id,
        audio_bytes=ms_to_bytes(ms),
    )


def audio_done(response_id: str) -> RealtimeEvent:
    return RealtimeEvent(type=RESPONSE_AUDIO_DONE, response_id=response_id)


def response_done(response_id: str, status: str = STATUS_COMPLETED) -> RealtimeEvent:
    if status not in {STATUS_COMPLETED, STATUS_CANCELLED}:
        raise ValueError("unsupported response status")
    return RealtimeEvent(type=RESPONSE_DONE, response_id=response_id, status=status)


def speech_started(playback_cursor_ms: int) -> RealtimeEvent:
    return RealtimeEvent(type=SPEECH_STARTED, playback_cursor_ms=playback_cursor_ms)


def encode_audio_b64(ms: int) -> str:
    """Build a base64 PCM16 blob of the given duration (for raw-event tests)."""

    return base64.b64encode(b"\x00" * ms_to_bytes(ms)).decode("ascii")


LIFECYCLE_TYPES = frozenset(
    {RESPONSE_CREATED, RESPONSE_AUDIO_DONE, RESPONSE_DONE}
)


def is_lifecycle_event(event: "RealtimeEvent") -> bool:
    return event.type in LIFECYCLE_TYPES


def parse_events(raw_events: list[dict]) -> list[RealtimeEvent]:
    """Decode a list of raw server payloads into events, in order."""

    return [RealtimeEvent.from_raw(raw) for raw in raw_events]

