from __future__ import annotations

"""Track the lifecycle of assistant responses in a session.

Only one response is active at a time, but several happen across a session. The
tracker remembers each response's output item, how much audio it generated, and
its status so the orchestrator always knows which response a barge-in targets.
"""

from dataclasses import dataclass, field

from realtime_models import (
    STATUS_CANCELLED,
    STATUS_COMPLETED,
    STATUS_IN_PROGRESS,
)


@dataclass
class ResponseRecord:
