"""Roll a session result up into the numbers support reviews after an incident."""

from client_commands import is_cancel, is_truncate
from realtime_models import STATUS_CANCELLED, STATUS_COMPLETED
from session_orchestrator import SessionResult


def summarize_session(result: SessionResult) -> dict[str, object]:
    return {
        "response_count": len(result.outcomes),
        "interruptions": result.interruptions,
        "cancel_commands": len(result.cancel_commands()),
        "truncate_commands": len(result.truncate_commands()),
        "total_generated_ms": sum(o.generated_ms for o in result.outcomes),
        "total_heard_ms": sum(o.heard_ms for o in result.outcomes),
        "total_stale_ms": result.total_stale_ms(),
        "cancelled": sum(1 for o in result.outcomes if o.status == STATUS_CANCELLED),
        "completed": sum(1 for o in result.outcomes if o.status == STATUS_COMPLETED),
    }


def per_response_rows(result: SessionResult) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for outcome in result.outcomes:
        rows.append(
            {
                "response_id": outcome.response_id,
                "item_id": outcome.item_id,
                "generated_ms": outcome.generated_ms,
                "heard_ms": outcome.heard_ms,
                "stale_ms": outcome.stale_ms,
                "status": outcome.status,
                "interrupted": outcome.interrupted,
            }
        )
    return rows


def stale_responses(result: SessionResult) -> list[str]:
    """Response ids that leaked audio after a barge-in."""

    return [o.response_id for o in result.outcomes if o.stale_ms > 0]


def truncation_points(result: SessionResult) -> dict[str, int]:
    return {c.item_id: c.audio_end_ms for c in result.commands if is_truncate(c)}


def cancelled_response_ids(result: SessionResult) -> list[str]:
    return [c.response_id for c in result.commands if is_cancel(c)]


def interrupted_response_ids(result: SessionResult) -> list[str]:
    return [o.response_id for o in result.outcomes if o.interrupted]


def heard_fraction(result: SessionResult) -> float:
    """Share of generated audio the user actually heard (1.0 if none generated)."""

    generated = sum(o.generated_ms for o in result.outcomes)
    if generated == 0:
        return 1.0
    return sum(o.heard_ms for o in result.outcomes) / generated

