from __future__ import annotations

"""Invariants a correct barge-in session must hold.

These are the checks support and QA run against a recorded session to decide
whether interruption handling behaved. They are intentionally about observable
behavior, not implementation.
"""

from client_commands import is_truncate
from session_orchestrator import SessionResult


class InvariantViolation(AssertionError):
    """Raised when a session result breaks a barge-in invariant."""


def check_no_stale_playback(result: SessionResult) -> bool:
    """No audio reached the speaker after the barge-in that ended a response."""

    return all(outcome.stale_ms == 0 for outcome in result.outcomes)


def check_played_within_generated(result: SessionResult) -> bool:
    """The user never heard more than the model generated."""

    return all(outcome.heard_ms <= outcome.generated_ms for outcome in result.outcomes)


def check_truncation_matches_heard(result: SessionResult) -> bool:
    """Every truncate cuts the item exactly at what the user heard."""

    heard_by_item = {o.item_id: o.heard_ms for o in result.outcomes}
    for command in result.commands:
        if not is_truncate(command):
            continue
        expected = heard_by_item.get(command.item_id)
        if expected is None or command.audio_end_ms != expected:
            return False
    return True


def check_interrupted_have_truncate(result: SessionResult) -> bool:
    """Each interrupted response produced a truncate for its item."""

    truncated_items = {c.item_id for c in result.commands if is_truncate(c)}
    for outcome in result.outcomes:
        if outcome.interrupted and outcome.item_id not in truncated_items:
            return False
    return True


def assert_session_valid(result: SessionResult) -> None:
    if not check_no_stale_playback(result):
        raise InvariantViolation("stale audio played after barge-in")
    if not check_played_within_generated(result):
        raise InvariantViolation("heard audio exceeds generated audio")
    if not check_truncation_matches_heard(result):
        raise InvariantViolation("truncation point does not match heard audio")
    if not check_interrupted_have_truncate(result):
        raise InvariantViolation("interrupted response missing truncate")

