from __future__ import annotations

"""Drive a Realtime session: consume server events, emit client commands.

This is the layer that ties everything together. It feeds audio into the
playback buffer, tracks response lifecycles, and on a barge-in produces the
cancel + truncate commands and tells the buffer where the user actually stopped
hearing the assistant. The order events arrive in is the whole game: audio for a
response can land after the barge-in that ended it.
"""

from dataclasses import dataclass, field

from interruption_policy import build_interruption_commands
from playback_buffer import PlaybackBuffer
from realtime_models import (
    RESPONSE_AUDIO_DELTA,
    RESPONSE_AUDIO_DONE,
    RESPONSE_CREATED,
    RESPONSE_DONE,
    SPEECH_STARTED,
    RealtimeEvent,
)
from response_tracker import ResponseTracker


@dataclass(frozen=True)
class ResponseOutcome:
    response_id: str
    item_id: str
    generated_ms: int
    heard_ms: int
    stale_ms: int
    status: str
    interrupted: bool


@dataclass
class SessionResult:
    commands: list[object] = field(default_factory=list)
    outcomes: list[ResponseOutcome] = field(default_factory=list)
    interruptions: int = 0

    def response(self, response_id: str) -> ResponseOutcome:
        for outcome in self.outcomes:
            if outcome.response_id == response_id:
                return outcome
        raise KeyError(response_id)

    def cancel_commands(self) -> list[object]:
        from client_commands import is_cancel

        return [c for c in self.commands if is_cancel(c)]

    def truncate_commands(self) -> list[object]:
        from client_commands import is_truncate

        return [c for c in self.commands if is_truncate(c)]

    def total_stale_ms(self) -> int:
        return sum(o.stale_ms for o in self.outcomes)


class RealtimeSessionOrchestrator:
    def __init__(self) -> None:
        self._tracker = ResponseTracker()
        self._buffer = PlaybackBuffer()
        self._commands: list[object] = []
        self._interruptions = 0

    def handle(self, event: RealtimeEvent) -> None:
        if event.type == RESPONSE_CREATED:
            self._on_created(event)
        elif event.type == RESPONSE_AUDIO_DELTA:
            self._on_audio(event)
        elif event.type == SPEECH_STARTED:
            self._on_barge_in(event)
        elif event.type == RESPONSE_AUDIO_DONE:
            pass
        elif event.type == RESPONSE_DONE:
            self._on_done(event)
        else:
            raise ValueError(f"unsupported event type: {event.type}")

    def run(self, events: list[RealtimeEvent]) -> SessionResult:
        for event in events:
            self.handle(event)
        return self._build_result()

    def _on_created(self, event: RealtimeEvent) -> None:
        if not event.response_id or not event.item_id:
            raise ValueError("response.created requires response_id and item_id")
        self._tracker.on_created(event.response_id, event.item_id)

    def _on_audio(self, event: RealtimeEvent) -> None:
        if not event.response_id:
            raise ValueError("audio delta requires response_id")
        ms = event.audio_ms
        self._tracker.on_audio(event.response_id, ms)
        self._buffer.accept_audio(event.response_id, ms)

    def _on_barge_in(self, event: RealtimeEvent) -> None:
        active = self._tracker.current()
        if active is None:
            raise ValueError("no active response to interrupt")

        cursor = min(event.playback_cursor_ms, active.generated_ms)
        commands = build_interruption_commands(active, cursor)
        self._buffer.interrupt(active.response_id, cursor)
        self._tracker.mark_interrupted(active.response_id)

        self._commands.extend(commands)
        self._interruptions += 1

    def _on_done(self, event: RealtimeEvent) -> None:
        if not event.response_id:
            raise ValueError("response.done requires response_id")
        self._tracker.on_done(event.response_id, event.status or "completed")

    def _build_result(self) -> SessionResult:
        outcomes: list[ResponseOutcome] = []
        for record in self._tracker.all_records():
            rid = record.response_id
            outcomes.append(
                ResponseOutcome(
                    response_id=rid,
                    item_id=record.item_id,
                    generated_ms=record.generated_ms,
                    heard_ms=self._buffer.heard_ms(rid),
                    stale_ms=self._buffer.stale_ms(rid),
                    status=record.status,
                    interrupted=self._buffer.is_interrupted(rid),
                )
            )
        return SessionResult(
            commands=list(self._commands),
            outcomes=outcomes,
            interruptions=self._interruptions,
        )


def run_session(events: list[RealtimeEvent]) -> SessionResult:
    return RealtimeSessionOrchestrator().run(events)

